const items = $input.all();

const historyData = items.find(
  item => Array.isArray(item.json.conversations)
);

const memoryData = items.find(
  item => typeof item.json.structured_memory_context === 'string'
);

const history = historyData?.json || {};
const memory = memoryData?.json || {};

const userId =
  $('WhatsApp Trigger1').first().json.messages[0].from;

const currentMessage =
  $('WhatsApp Trigger1').first().json.messages[0].text?.body || '';

const conversations = history.conversations || [];

const conversationContext = conversations
  .map(item => {
    const role = item.role || 'unknown';
    const content =
      item.content ||
      item.message ||
      item.text ||
      '';

    return `${role}: ${content}`;
  })
  .join('\n');

const structuredMemoryContext =
  memory.structured_memory_context || '';

return [
  {
    json: {
      user_id: userId,
      current_message: currentMessage,
      conversation_context: conversationContext,
      structured_memory_context: structuredMemoryContext,
      history_count: history.count || 0,
      memory_count: memory.count || 0
    }
  }
];

