parameters.jsCode:
const output = ($json.output || '').trim();

const user_id =
  $('WhatsApp Trigger1').first().json.messages[0].from;

// No extractor output
if (!output) {
  return [{
    json: {
      user_id,
      action: "NONE",
      memory_extraction_failed: false
    }
  }];
}

let data;

try {
  data = JSON.parse(output);
} catch (error) {

  console.log(
    "Memory Extractor returned invalid JSON:",
    output
  );

  return [{
    json: {
      user_id,
      action: "NONE",
      memory_extraction_failed: true,
      error: "invalid_json"
    }
  }];
}

// Invalid structure
if (!Array.isArray(data.actions)) {
  return [{
    json: {
      user_id,
      action: "NONE",
      memory_extraction_failed: true,
      error: "invalid_actions"
    }
  }];
}

const validActions = [
  "CREATE",
  "UPDATE",
  "DELETE",
  "NONE"
];

const actions = data.actions.filter(action =>
  action &&
  validActions.includes(action.action)
);

if (actions.length === 0) {
  return [{
    json: {
      user_id,
      action: "NONE",
      memory_extraction_failed: false
    }
  }];
}

return actions.map(action => ({
  json: {
    user_id,
    action: action.action,
    category: action.category ?? null,
    key: action.key ?? null,
    value: action.value ?? null,
    importance: Number(action.importance ?? 0.5),
    confidence: Number(action.confidence ?? 1.0),
    memory_type: action.memory_type ?? "long_term",
    expires_at: action.expires_at ?? null,
    source: "conversation",
    memory_extraction_failed: false
  }
}));

const memories = Array.isArray($json.memories)
  ? $json.memories
  : [];

if (memories.length === 0) {
  return [{
    json: {
      structured_memory_context: "",
      memories: [],
      memory_available: false
    }
  }];
}

const context = memories
  .map(memory =>
    `- ${memory.category}: ${memory.key} = ${memory.value}`
  )
  .join("\n");

return [{
  json: {
    structured_memory_context:
      "RELEVANT USER MEMORIES:\n" + context,
    memories,
    memory_available: true
  }
}];

const message = (
  $json.messages?.[0]?.text?.body ||
  $json.current_message ||
  ''
).trim();

const lower = message.toLowerCase();

const skipPatterns = [
  /^hi$/,
  /^hello$/,
  /^hey$/,
  /^hey there$/,
  /^good morning$/,
  /^good afternoon$/,
  /^good evening$/,
  /^thanks$/,
  /^thank you$/,
  /^ok$/,
  /^okay$/,
  /^k$/,
  /^yes$/,
  /^no$/,
  /^sure$/,
  /^great$/,
  /^cool$/,
  /^nice$/,
  /^👍$/,
  /^😊$/,
  /^😂$/
];

const shouldRetrieve = !skipPatterns.some(pattern =>
  pattern.test(lower)
);

return {
  json: {
    ...$json,
    current_message: message,
    should_retrieve_memory: shouldRetrieve
  }
};

const memories = Array.isArray($json.memories)
  ? $json.memories
  : [];

if (memories.length === 0) {
  return [{
    json: {
      structured_memory_context: "",
      memories: [],
      memory_available: false
    }
  }];
}

const context = memories
  .map(memory =>
    `- ${memory.category}: ${memory.key} = ${memory.value}`
  )
  .join("\n");

return [{
  json: {
    structured_memory_context:
      "RELEVANT USER MEMORIES:\n" + context,
    memories,
    memory_available: true
  }
}];

const action = String($json.action || "").toUpperCase();
const category = String($json.category || "").trim();
const key = String($json.key || "").trim();
const value = $json.value ?? null;

const validActions = [
  "CREATE",
  "UPDATE",
  "DELETE",
  "NONE"
];

// --------------------------------------------------
// Invalid action
// --------------------------------------------------

if (!validActions.includes(action)) {
  return {
    json: {
      ...$json,
      action: "NONE",
      validation_failed: true,
      validation_error: "invalid_action"
    }
  };
}

// --------------------------------------------------
// NONE needs no memory fields
// --------------------------------------------------

if (action === "NONE") {
  return {
    json: {
      ...$json,
      action: "NONE",
      validation_failed: false
    }
  };
}

// --------------------------------------------------
// CREATE / UPDATE / DELETE require category + key
// --------------------------------------------------

if (!category || !key) {
  return {
    json: {
      ...$json,
      action: "NONE",
      validation_failed: true,
      validation_error: "missing_category_or_key"
    }
  };
}

// --------------------------------------------------
// CREATE / UPDATE require a value
// --------------------------------------------------

if (
  (action === "CREATE" || action === "UPDATE") &&
  (value === null || String(value).trim() === "")
) {
  return {
    json: {
      ...$json,
      action: "NONE",
      validation_failed: true,
      validation_error: "missing_value"
    }
  };
}

// --------------------------------------------------
// Valid action
// --------------------------------------------------

return {
  json: {
    ...$json,
    action,
    category,
    key,
    value,
    validation_failed: false
  }
};
